//! Outlines drawn with `<curveLocal>` lines, arcs and paramPoly3 curves.
//!
//! `curve_local.xodr` is generated by `scenariogeneration` (see
//! `curve_local.py`). Its road 1 is a flat straight from the origin heading
//! +X, so a road station `(s, t)` is the point `(s, t, 0)`.

use std::f32::consts::PI;

use xodr::{
    load_file_with_provenance, Corner, Object, Point, Provenance, RoadNetwork, Shape, Warning,
};

const FIXTURE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/curve_local.xodr");

fn load() -> (RoadNetwork, Provenance) {
    load_file_with_provenance(FIXTURE).expect("import")
}

fn named<'a>(net: &'a RoadNetwork, name: &str) -> Option<&'a Object> {
    net.objects().iter().find(|o| o.name == name)
}

fn corners(object: &Object) -> &[Corner] {
    match &object.shape {
        Shape::Outline { corners, .. } => corners,
        other => panic!("{} is not an outline: {other:?}", object.name),
    }
}

/// A corner's base in the frame of an object at `(s, t)` turned `hdg`.
fn local(s: f32, t: f32, hdg: f32, p: Point) -> (f32, f32) {
    let (dx, dy) = (p.x - s, p.y - t);
    let (sin, cos) = hdg.sin_cos();
    (dx * cos + dy * sin, -dx * sin + dy * cos)
}

/// How far `(u, v)` is from a stadium `long` metres long: the lines `v = 0`
/// and `v = 4` for `u` in `[0, long]`, and the half circles of radius 2
/// round `(long, 2)` and `(0, 2)` beyond them.
fn off_stadium(long: f32, (u, v): (f32, f32)) -> f32 {
    let end = if u > long {
        Some(long)
    } else if u < 0.0 {
        Some(0.0)
    } else {
        None
    };
    match end {
        Some(c) => ((u - c).hypot(v - 2.0) - 2.0).abs(),
        None => v.abs().min((v - 4.0).abs()),
    }
}

/// The area of a polygon in plan, by the shoelace formula.
fn area(corners: &[Corner]) -> f32 {
    let n = corners.len();
    (0..n)
        .map(|i| {
            let (a, b) = (corners[i].base, corners[(i + 1) % n].base);
            a.x * b.y - b.x * a.y
        })
        .sum::<f32>()
        .abs()
        / 2.0
}

#[test]
fn lines_and_arcs_trace_a_smooth_outline() {
    let (net, _) = load();
    let island = named(&net, "Island").expect("the island");
    let corners = corners(island);
    assert!(corners.len() > 40, "{} corners", corners.len());
    for c in corners {
        let off = off_stadium(10.0, local(10.0, -5.0, 0.0, c.base));
        assert!(off < 1e-3, "{:?} is {off} m off the stadium", c.base);
        assert!((c.top.z - c.base.z - 0.3).abs() < 1e-5, "{c:?}");
    }
    let want = 40.0 + PI * 4.0;
    let got = area(corners);
    assert!(
        (got - want).abs() / want < 0.005,
        "area {got}, expected {want}"
    );
}

#[test]
fn a_marking_between_two_curves_follows_the_curve_between_them() {
    let (net, _) = load();
    let island = named(&net, "Island").expect("the island");
    let [arc] = &island.markings[..] else {
        panic!("one marking: {:?}", island.markings);
    };
    assert!(arc.pieces.len() > 8, "{} pieces", arc.pieces.len());
    for [a, b, c, d] in &arc.pieces {
        let mid = a.lerp(*c, 0.5).lerp(b.lerp(*d, 0.5), 0.5);
        let (u, v) = local(10.0, -5.0, 0.0, mid);
        let off = ((u - 10.0).hypot(v - 2.0) - 2.0).abs();
        assert!(
            u >= 10.0 - 1e-3 && off < 0.02,
            "{mid:?} is off the half circle"
        );
    }
}

#[test]
fn a_border_runs_round_every_sample_of_the_curves() {
    let (net, _) = load();
    let island = named(&net, "Island").expect("the island");
    let [kerb] = &island.borders[..] else {
        panic!("one border: {:?}", island.borders);
    };
    assert_eq!(kerb.pieces.len(), corners(island).len());
}

#[test]
fn an_arc_with_no_length_runs_to_the_next_corner_and_a_lone_one_closes_on_itself() {
    let (net, _) = load();
    let lens = named(&net, "Lens").expect("the lens");
    let corners = corners(lens);
    assert!(corners.len() >= 32, "{} corners", corners.len());
    for c in corners {
        let (u, v) = local(30.0, 5.0, 0.0, c.base);
        let off = (u.hypot(v - 2.0) - 2.0).abs();
        assert!(off < 1e-3, "{:?} is {off} m off the circle", c.base);
    }
    let want = PI * 4.0;
    let got = area(corners);
    assert!(
        (got - want).abs() / want < 0.01,
        "area {got}, expected {want}"
    );
}

#[test]
fn a_param_poly3_and_lines_with_no_heading_or_length_reach_the_next_corner() {
    let (net, _) = load();
    let wave = named(&net, "Wave").expect("the wave");
    let corners = corners(wave);
    let (curve, ends) = corners.split_at(corners.len() - 3);
    let at = |c: &Corner| local(45.0, -6.0, 0.5, c.base);
    for (c, want) in ends.iter().zip([(8.0, 0.0), (8.0, 2.0), (8.0, 3.0)]) {
        let got = at(c);
        assert!(
            (got.0 - want.0).hypot(got.1 - want.1) < 1e-3,
            "{got:?}, expected {want:?}"
        );
    }
    let last = ends[2];
    assert!((last.top.z - last.base.z - 2.0).abs() < 1e-5, "{last:?}");
    assert!(curve.len() >= 8, "{} samples", curve.len());
    for c in curve {
        let (u, v) = at(c);
        let p = u / 8.0;
        assert!(
            (v - (4.0 * p - 4.0 * p * p)).abs() < 1e-3,
            "({u}, {v}) off the curve"
        );
        let height = c.top.z - c.base.z;
        assert!(
            (height - (1.0 + p)).abs() < 1e-3,
            "height {height} at p = {p}"
        );
    }
}

#[test]
fn curves_that_do_not_join_are_joined_straight_with_a_warning() {
    let (net, provenance) = load();
    let broken = named(&net, "Broken").expect("the broken outline");
    let got: Vec<(f32, f32)> = corners(broken)
        .iter()
        .map(|c| local(50.0, 4.0, 0.0, c.base))
        .collect();
    let want = [(0.0, 0.0), (4.0, 0.0), (4.0, 1.0), (4.0, 3.0), (0.0, 3.0)];
    assert_eq!(got.len(), want.len(), "{got:?}");
    for (g, w) in got.iter().zip(want) {
        assert!((g.0 - w.0).hypot(g.1 - w.1) < 1e-3, "{got:?}");
    }
    let gaps: Vec<(&str, f64)> = provenance
        .warnings
        .iter()
        .filter_map(|w| match w {
            Warning::OutlineGap { object_id, gap, .. } => Some((object_id.as_str(), *gap)),
            _ => None,
        })
        .collect();
    assert_eq!(gaps.len(), 1, "{gaps:?}");
    assert_eq!(gaps[0].0, "4");
    assert!((gaps[0].1 - 4.0).abs() < 1e-6, "{gaps:?}");
}

#[test]
fn an_arc_length_param_poly3_with_no_length_drops_its_outline() {
    let (net, provenance) = load();
    let unsized_ = named(&net, "Unsized").expect("the object keeps its box");
    assert!(matches!(unsized_.shape, Shape::Solid { .. }));
    assert!(provenance
        .warnings
        .iter()
        .any(|w| matches!(w, Warning::OutlineDropped { object_id, .. } if object_id == "5")));
}

#[test]
fn a_repeat_of_curves_too_many_corners_is_left_out_with_a_warning() {
    let (net, provenance) = load();
    assert!(named(&net, "Swarm").is_none());
    let too_many = provenance
        .warnings
        .iter()
        .any(|w| matches!(w, Warning::TooManyCopies { object_id, .. } if object_id == "6"));
    assert!(too_many, "{:?}", provenance.warnings);
}

#[test]
fn a_curve_with_no_heading_goes_on_from_the_curve_before() {
    let (net, _) = load();
    let smooth = named(&net, "Smooth").expect("the smooth island");
    let corners = corners(smooth);
    assert!(corners.len() > 40, "{} corners", corners.len());
    for c in corners {
        let off = off_stadium(4.0, local(10.0, 6.0, 0.0, c.base));
        assert!(off < 1e-3, "{:?} is {off} m off the stadium", c.base);
    }
}

#[test]
fn a_heading_that_leaves_a_gap_gives_way_to_the_curve_before_with_a_warning() {
    let (net, provenance) = load();
    let misheaded = named(&net, "Misheaded").expect("the misheaded island");
    for c in corners(misheaded) {
        let off = off_stadium(4.0, local(40.0, -6.0, 0.0, c.base));
        assert!(off < 1e-3, "{:?} is {off} m off the stadium", c.base);
    }
    let turned: Vec<&str> = provenance
        .warnings
        .iter()
        .filter_map(|w| match w {
            Warning::CurveHeadingIgnored { object_id, .. } => Some(object_id.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(turned, ["8"]);
    let gaps = provenance
        .warnings
        .iter()
        .any(|w| matches!(w, Warning::OutlineGap { object_id, .. } if object_id == "8"));
    assert!(!gaps, "the misheaded island joins up");
}
